	protected void assertModuleRow(int pos, object @object, string name, Address start, Address end,
			long length) {
		ValueRow row = provider.modulesPanel.getAllItems().get(pos);
		var tableModel = QueryPanelTestHelper.getTableModel(provider.modulesPanel);
		GhidraTable table = QueryPanelTestHelper.getTable(provider.modulesPanel);
		DynamicTableColumn<ValueRow,object, Trace> nameCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Name", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> baseCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Base", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> maxCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Max", typeof(ValueProperty))
				.column();
		DynamicTableColumn<ValueRow,object, Trace> lengthCol = QueryPanelTestHelper
				.getColumnByNameAndType(tableModel, table, "Length", typeof(ValueProperty))
				.column();

		assertSame(@object, row.getValue().getValue());
		assertEquals(name, rowColVal(row, nameCol));
		assertEquals(start, rowColVal(row, baseCol));
		assertEquals(end, rowColVal(row, maxCol));
		assertEquals(length, rowColVal(row, lengthCol));
	}

